<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Kanban Board</title>
<style>
*{box-sizing:border-box}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Ubuntu,sans-serif;background:#f5f7fb;color:#111;padding:24px}
h1{font-size:20px;margin:0 0 16px}
.controls{display:flex;gap:8px;margin-bottom:16px}
#new-card{flex:1;padding:10px 12px;border:1px solid #cbd5e1;border-radius:10px;font-size:14px}
#add-card{padding:10px 16px;border:none;background:#2563eb;color:#fff;border-radius:10px;font-weight:600;cursor:pointer}
#add-card:hover{background:#1d4ed8}
.board{display:flex;gap:16px;align-items:flex-start}
.column{background:#fff;border-radius:12px;box-shadow:0 2px 10px rgba(0,0,0,.08);flex:1;min-width:280px;display:flex;flex-direction:column;max-height:70vh}
.header{padding:12px 16px;border-bottom:1px solid #eef2f7;font-weight:700;display:flex;justify-content:space-between;align-items:center}
.header .count{background:#e2e8f0;color:#334155;padding:2px 8px;border-radius:999px;font-size:12px;font-weight:600}
.cards{padding:12px;flex:1;overflow:auto;display:flex;flex-direction:column;gap:10px}
.card{background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:10px 12px;display:flex;justify-content:space-between;align-items:center;cursor:grab;box-shadow:0 1px 2px rgba(0,0,0,.04)}
.card:active{cursor:grabbing}
.card .title{word-break:break-word;flex:1;margin-right:8px}
.card-del{background:transparent;border:none;font-size:18px;line-height:1;cursor:pointer;color:#94a3b8}
.card-del:hover{color:#e11d48}
.column.drag-over{outline:2px dashed #2563eb}
</style>
</head>
<body>
<h1>Kanban Board</h1>
<div class="controls">
  <input id="new-card" placeholder="New task..." />
  <button id="add-card">Add</button>
</div>
<div class="board">
  <div id="col-todo" class="column" data-col="todo">
    <div class="header">To Do <span class="count">0</span></div>
    <div class="cards"></div>
  </div>
  <div id="col-doing" class="column" data-col="doing">
    <div class="header">Doing <span class="count">0</span></div>
    <div class="cards"></div>
  </div>
  <div id="col-done" class="column" data-col="done">
    <div class="header">Done <span class="count">0</span></div>
    <div class="cards"></div>
  </div>
</div>
<script>
const STORAGE_KEY='kanban-board-v1';
let state={todo:[],doing:[],done:[]};

function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}
function load(){
  try{const raw=localStorage.getItem(STORAGE_KEY); if(raw){state=JSON.parse(raw);}}catch(e){}
  if(!state.todo) state.todo=[];
  if(!state.doing) state.doing=[];
  if(!state.done) state.done=[];
}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2);}
function findCard(id){
  for(const col of ['todo','doing','done']){
    const idx=state[col].findIndex(c=>c.id===id);
    if(idx>-1) return {col,idx,card:state[col][idx]};
  }
  return null;
}
function updateCounts(){
  for(const col of ['todo','doing','done']){
    const el=document.querySelector('#col-'+col+' .count');
    if(el) el.textContent=state[col].length;
  }
}
function makeCard(card){
  const el=document.createElement('div');
  el.className='card';
  el.draggable=true;
  el.dataset.id=card.id;
  const title=document.createElement('span');
  title.className='title';
  title.textContent=card.title;
  const del=document.createElement('button');
  del.className='card-del';
  del.textContent='×';
  del.setAttribute('aria-label','Delete');
  el.appendChild(title);
  el.appendChild(del);
  el.addEventListener('dragstart',e=>{
    e.dataTransfer.setData('text/plain',card.id);
    e.dataTransfer.effectAllowed='move';
  });
  del.addEventListener('click',e=>{
    e.stopPropagation();
    deleteCard(el);
  });
  return el;
}
function deleteCard(el){
  const id=el.dataset.id;
  const found=findCard(id);
  if(!found) return;
  state[found.col].splice(found.idx,1);
  el.remove();
  save(); updateCounts();
}
function render(){
  for(const col of ['todo','doing','done']){
    const container=document.querySelector('#col-'+col+' .cards');
    container.innerHTML='';
    for(const card of state[col]){
      container.appendChild(makeCard(card));
    }
  }
  updateCounts();
}
function addCard(title){
  const t=title.trim();
  if(!t) return;
  const card={id:uid(),title:t};
  state.todo.push(card);
  const container=document.querySelector('#col-todo .cards');
  container.appendChild(makeCard(card));
  save(); updateCounts();
  document.getElementById('new-card').value='';
}
document.addEventListener('DOMContentLoaded',()=>{
  load();
  render();
  document.getElementById('add-card').addEventListener('click',()=>addCard(document.getElementById('new-card').value));
  document.getElementById('new-card').addEventListener('keydown',e=>{if(e.key==='Enter') addCard(e.target.value);});
  for(const col of ['todo','doing','done']){
    const column=document.getElementById('col-'+col);
    column.addEventListener('dragover',e=>{e.preventDefault(); column.classList.add('drag-over');});
    column.addEventListener('dragleave',()=>column.classList.remove('drag-over'));
    column.addEventListener('drop',e=>{
      e.preventDefault();
      column.classList.remove('drag-over');
      const id=e.dataTransfer.getData('text/plain');
      if(!id) return;
      const found=findCard(id);
      if(!found) return;
      const targetCol=column.dataset.col;
      if(found.col===targetCol) return;
      state[found.col].splice(found.idx,1);
      state[targetCol].push(found.card);
      const cardEl=document.querySelector(`.card[data-id="${id}"]`);
      if(cardEl){
        document.querySelector('#col-'+targetCol+' .cards').appendChild(cardEl);
      }
      save(); updateCounts();
    });
  }
});
</script>
</body>
</html>
